import{_ as r,a0 as s,w as l,s as i,I as e,x as a,a1 as n,A as p,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在 Fedora 上使用 Steam play 和 Proton 來玩 Windows 遊戲 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 上使用 Steam play 和 Proton 來玩 Windows 遊戲 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 上使用 Steam play 和 Proton 來玩 Windows 遊戲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 上使用 Steam play 和 Proton 來玩 Windows 遊戲 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181008 Play Windows games on Fedora with Steam Play and Proton","title":"在 Fedora 上使用 Steam play 和 Proton 來玩 Windows 遊戲","tag":"201811","desc":""},"relativePath":"201811/20181008 Play Windows games on Fedora with Steam Play and Proton.md","filePath":"[post].md"}'),d={name:"201811/20181008 Play Windows games on Fedora with Steam Play and Proton.md"};function g(u,t,f,w,S,P){const o=s("Link");return l(),i("div",null,[t[18]||(t[18]=e("h1",{id:"在-fedora-上使用-steam-play-和-proton-來玩-windows-遊戲",tabindex:"-1"},[a("在 Fedora 上使用 Steam play 和 Proton 來玩 Windows 遊戲 "),e("a",{class:"header-anchor",href:"#在-fedora-上使用-steam-play-和-proton-來玩-windows-遊戲","aria-label":"Permalink to “在 Fedora 上使用 Steam play 和 Proton 來玩 Windows 遊戲”"},"​")],-1)),t[19]||(t[19]=e("p",null,[e("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/09/steam-proton-816x345.jpg",alt:""})],-1)),e("p",null,[t[1]||(t[1]=a("之前，Steam ",-1)),n(o,{href:"https://steamcommunity.com/games/221410/announcements/detail/1696055855739350561"},{default:p(()=>[...t[0]||(t[0]=[a("宣佈",-1)])]),_:1}),t[2]||(t[2]=a("要給 Steam Play 增加一個新組件，用於支持在 Linux 平台上使用 Proton 來玩 Windows 的遊戲，這個組件是 WINE 的一個分支。這個功能仍然處於測試階段，且並非對所有遊戲都有效。這裏有一些關於 Steam 和 Proton 的細節。",-1))]),t[20]||(t[20]=m('<p>據 Steam 網站稱，測試版本中有以下這些新功能：</p><ul><li>現在沒有 Linux 版本的 Windows 遊戲可以直接從 Linux 上的 Steam 客户端進行安裝和運行，並且有完整、原生的 Steamworks 和 OpenVR 的支持。</li><li>現在 DirectX 11 和 12 的實現都基於 Vulkan，它可以提高遊戲的兼容性並減小遊戲性能收到的影響。</li><li>全屏支持已經得到了改進，全屏遊戲時可以無縫擴展到所需的顯示程度，而不會干擾到顯示屏本身的分辨率或者説需要使用虛擬桌面。</li><li>改進了對遊戲控制器的支持，遊戲自動識別所有 Steam 支持的控制器，比起遊戲的原始版本，能夠獲得更多開箱即用的控制器兼容性。</li><li>和 vanilla WINE 比起來，遊戲的多線程性能得到了極大的提高。</li></ul><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>如果你有興趣，想嘗試一下 Steam 和 Proton。請按照下面這些簡單的步驟進行操作。（請注意，如果你已經安裝了最新版本的 Steam，可以忽略啓用 Steam 測試版這個第一步。在這種情況下，你不再需要通過 Steam 測試版來使用 Proton。）</p><p>打開 Steam 並登陸到你的帳户，這個截屏示例顯示的是在使用 Proton 之前僅支持 22 個遊戲。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/listOfGamesLinux-768x505.png" alt=""></p><p>現在點擊客户端頂部的 “Steam” 選項，這會顯示一個下拉菜單。然後選擇“設置”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/1-768x432.png" alt=""></p><p>現在彈出了設置窗口，選擇“賬户”選項，並在 “參與 Beta 測試” 旁邊，點擊“更改”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/2-768x503.png" alt=""></p><p>現在將 “None” 更改為 “Steam Beta Update”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/4.png" alt=""></p><p>點擊“確定”，然後系統會提示你重新啓動。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/6.png" alt=""></p><p>讓 Steam 下載更新，這會需要一段時間，具體需要多久這要取決於你的網絡速度和電腦配置。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/7.png" alt=""></p><p>在重新啓動之後，返回到上面的設置窗口。這次你會看到一個新選項。確定勾選了“為提供支持的遊戲使用 Stream Play” 、“讓所有的遊戲都使用 Steam Play 運行”，“使用這個工具替代 Steam 中游戲特定的選項”。這個兼容性工具應該就是 Proton。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/10.png" alt=""></p><p>Steam 客户端會要求你重新啓動，照做，然後重新登錄你的 Steam 賬户，你的 Linux 的遊戲庫就能得到擴展了。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/12-768x503.png" alt=""></p><h3 id="使用-steam-play-來安裝一個-windows-遊戲" tabindex="-1">使用 Steam Play 來安裝一個 Windows 遊戲 <a class="header-anchor" href="#使用-steam-play-來安裝一個-windows-遊戲" aria-label="Permalink to “使用 Steam Play 來安裝一個 Windows 遊戲”">​</a></h3><p>現在你已經啓用 Proton，開始安裝遊戲，選擇你想要安裝的遊戲，然後你會發現這個安裝過程類似於在 Steam 上安裝一個普通遊戲，如下面這些截圖所示。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/13-768x501.png" alt=""></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/14-768x498.png" alt=""></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/15-768x501.png" alt=""></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/16-768x500.png" alt=""></p><p>在下載和安裝完遊戲後，你就可以開始玩了。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/Screenshot-from-2018-08-30-15-14-59-768x432.png" alt=""></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/Screenshot-from-2018-08-30-15-19-34-768x432.png" alt=""></p><p>一些遊戲可能會受到 Proton 測試性質的影響，在這個叫 Chantelise 遊戲中，沒有了聲音並且幀率很低。請記住這個功能仍然在測試階段，Fedora 不會對結果負責。如果你想要了解更多，社區已經創建了一個 Google 文檔，這個文檔裏有已經測試過的遊戲的列表。</p><hr>',31)),e("p",null,[t[4]||(t[4]=a("via: ",-1)),n(o,{href:"https://fedoramagazine.org/play-windows-games-steam-play-proton/"},{default:p(()=>[...t[3]||(t[3]=[a("https://fedoramagazine.org/play-windows-games-steam-play-proton/",-1)])]),_:1})]),e("p",null,[t[9]||(t[9]=a("作者：",-1)),n(o,{href:"https://fedoramagazine.org/author/patxi/"},{default:p(()=>[...t[5]||(t[5]=[a("Francisco J. Vergara Torres",-1)])]),_:1}),t[10]||(t[10]=a(" 選題：",-1)),n(o,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[6]||(t[6]=[a("lujun9972",-1)])]),_:1}),t[11]||(t[11]=a(" 譯者：",-1)),n(o,{href:"https://github.com/hopefully2333"},{default:p(()=>[...t[7]||(t[7]=[a("hopefully2333",-1)])]),_:1}),t[12]||(t[12]=a(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[8]||(t[8]=[a("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=a("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[13]||(t[13]=[a("LCTT",-1)])]),_:1}),t[16]||(t[16]=a(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:p(()=>[...t[14]||(t[14]=[a("Linux中國",-1)])]),_:1}),t[17]||(t[17]=a(" 榮譽推出",-1))])])}const T=r(d,[["render",g]]);export{h as __pageData,T as default};
